-- Mythic+ vendors (mod-coa-mythic-plus). Edrim Skysong <Mythic Items> sells the Mythic Dungeon items by slot
-- for Mythic Coins; Markus / Mar'toge <Mark of Triumph Exchange> sell the Mark of Triumph items and, by slot, the Heroic
-- Dungeon items of the Exiles vendor list of 1414503 for Marks of Triumph. The gossip scripts open these lists:
-- 9416001-9416016 Edrim by slot, 9414500 Mark of Triumph items, 9414501-9414516 Heroic Dungeon items by slot.
-- Prices from tester screenshots and recollection: coins 525 head/shoulders/chest/legs, 475 neck/rings/trinkets,
-- 425 back/hands/feet/waist/wrists, 600 one-hand/off-hand/ranged, 1200 two-hand; marks 80 head/shoulders/chest/legs/
-- two-hand, 45 one-hand/ranged, 60 trinkets, 55 the rest; every Heroic Dungeon item 30. Edrim sells only the epic
-- Mythic Dungeon items (12 green world drops have no epic version). Markus and Mar'toge use stand-in models: Ascension's
-- 660000/660001 are not in the server's CreatureDisplayInfo.dbc. Romus the Redeemer has no function yet.
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (400000, 1414502, 1414503);

UPDATE `creature_template` SET `npcflag` = 129, `ScriptName` = 'npc_coa_mythic_items' WHERE `entry` = 416000;
DELETE FROM `creature` WHERE `id` = 416000 AND `map` = 429;

DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 9416001 AND 9416016 OR `entry` BETWEEN 9414500 AND 9414516;

DELETE FROM `npc_text` WHERE `ID` IN (9416000, 9414500);

-- Mythical Boon (80215, as captured from the live client): only in a running keystone. Right-click gives a random
-- Mythical Boon and the boon vanishes. The boon items work only inside a running keystone.
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (80215);
UPDATE `item_template` SET `ScriptName` = 'item_coa_mythic_boon' WHERE `entry` IN (2104920, 2104921, 2104922, 2104923,
    2104925, 2104926, 2104927, 2104928, 2104929, 2104930, 2104931, 2104932, 2104935);
